<?php
declare(strict_types=1);

function inventory_ops_save_policy(array $record): array
{
    inventory_ops_require_tables();$record['updated_at']=date('Y-m-d H:i:s');$record['created_at']=$record['created_at']??$record['updated_at'];
    if(data_is_demo())return inventory_ops_demo_save('inventory_replenishment_policies',$record,'inventory_ops_demo_policies');
    $pdo=production_database_connection();$id=(int)($record['id']??0);$params=[$record['policy_number'],$record['company_id'],$record['inventory_location_id'],$record['item_id'],$record['minimum_quantity'],$record['maximum_quantity'],$record['reorder_point'],$record['safety_stock'],$record['lead_time_days'],$record['review_frequency_days'],$record['preferred_supplier_id'],$record['owner_id'],$record['reviewer_id'],$record['status'],$record['evidence_note']];if($id){$params[]=$id;$pdo->prepare('UPDATE inventory_replenishment_policies SET policy_number=?,company_id=?,inventory_location_id=?,item_id=?,minimum_quantity=?,maximum_quantity=?,reorder_point=?,safety_stock=?,lead_time_days=?,review_frequency_days=?,preferred_supplier_id=?,owner_id=?,reviewer_id=?,status=?,evidence_note=?,updated_at=NOW() WHERE id=?')->execute($params);}else{$pdo->prepare('INSERT INTO inventory_replenishment_policies (policy_number,company_id,inventory_location_id,item_id,minimum_quantity,maximum_quantity,reorder_point,safety_stock,lead_time_days,review_frequency_days,preferred_supplier_id,owner_id,reviewer_id,status,evidence_note) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute($params);$id=(int)$pdo->lastInsertId();}$record['id']=$id;return $record;
}

