    $pdo=production_database_connection();$id=(int)($record['id']??0);$fields=['recommendation_number','policy_id','company_id','inventory_location_id','item_id','available_quantity','allocated_quantity','open_po_quantity','forecast_quantity','safety_stock_quantity','recommended_quantity','estimated_unit_cost','estimated_value','recommendation_type','source_inventory_location_id','preferred_supplier_id','required_date','status','approval_id','converted_request_id','converted_transfer_id','evidence_note','created_by'];$values=[];foreach($fields as $f)$values[]=$record[$f]??null;if($id){$set=implode(',',array_map(static fn(string $f):string=>$f.'=?',$fields));$values[]=$id;$pdo->prepare('UPDATE inventory_replenishment_recommendations SET '.$set.',updated_at=NOW() WHERE id=?')->execute($values);}else{$pdo->prepare('INSERT INTO inventory_replenishment_recommendations ('.implode(',',$fields).') VALUES ('.implode(',',array_fill(0,count($fields),'?')).')')->execute($values);$id=(int)$pdo->lastInsertId();}$record['id']=$id;return $record;
}

