function inventory_ops_add_transfer_event(int $transferId,string $type,?string $from,?string $to,string $severity,string $evidence): array
{
    inventory_ops_require_tables();$record=['id'=>null,'transfer_request_id'=>$transferId,'event_type'=>$type,'from_status'=>$from,'to_status'=>$to,'severity'=>$severity,'evidence_note'=>mb_substr($evidence,0,5000),'created_by'=>(int)current_user()['id'],'created_at'=>date('Y-m-d H:i:s')];if(data_is_demo())return inventory_ops_demo_save('inventory_transfer_events',$record,'inventory_ops_demo_transfer_events');$pdo=production_database_connection();$pdo->prepare('INSERT INTO inventory_transfer_events (transfer_request_id,event_type,from_status,to_status,severity,evidence_note,created_by) VALUES (?,?,?,?,?,?,?)')->execute([$transferId,$type,$from,$to,$severity,$record['evidence_note'],$record['created_by']]);$record['id']=(int)$pdo->lastInsertId();return $record;
}

function inventory_ops_add_event(int $companyId,int $locationId,?int $itemId,string $entityType,int $entityId,string $type,?string $from,?string $to,string $severity,float $quantity,float $value,string $evidence): array
{
    inventory_ops_require_tables();$record=['id'=>null,'company_id'=>$companyId,'inventory_location_id'=>$locationId,'item_id'=>$itemId&&$itemId>0?$itemId:null,'entity_type'=>$entityType,'entity_id'=>$entityId,'event_type'=>$type,'from_status'=>$from,'to_status'=>$to,'severity'=>$severity,'quantity'=>$quantity,'value_amount'=>$value,'evidence_note'=>mb_substr($evidence,0,5000),'created_by'=>(int)current_user()['id'],'created_at'=>date('Y-m-d H:i:s')];if(data_is_demo())return inventory_ops_demo_save('inventory_governance_events',$record,'inventory_ops_demo_events');$pdo=production_database_connection();$pdo->prepare('INSERT INTO inventory_governance_events (company_id,inventory_location_id,item_id,entity_type,entity_id,event_type,from_status,to_status,severity,quantity,value_amount,evidence_note,created_by) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$companyId,$locationId,$record['item_id'],$entityType,$entityId,$type,$from,$to,$severity,$quantity,$value,$record['evidence_note'],$record['created_by']]);$record['id']=(int)$pdo->lastInsertId();return $record;
}

